const upsertIntegrationItem = `-- name: UpsertIntegrationItem :execrows
INSERT INTO integration_items (
  organization_id, id, integration_id, item_type, external_id, external_account_code, external_name,
  created_at, updated_at
) VALUES (
  $1, $2, $3, $4, $5, $6, $7,
  $8, $9
)
ON CONFLICT (organization_id, integration_id, item_type, external_id) DO UPDATE SET
  external_account_code = EXCLUDED.external_account_code,
  external_name = EXCLUDED.external_name,
  updated_at = EXCLUDED.updated_at
`

type UpsertIntegrationItemParams struct {
	OrganizationID      uuid.UUID
	ID                  uuid.UUID
	IntegrationID       uuid.UUID
	ItemType            string
	ExternalID          string
	ExternalAccountCode *string
	ExternalName        *string
	CreatedAt           time.Time
	UpdatedAt           time.Time
}

// An item already cached under the same (integration, item type, external
// id) keeps its id and creation instant.
func (q *Queries) UpsertIntegrationItem(ctx context.Context, arg UpsertIntegrationItemParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertIntegrationItem,
		arg.OrganizationID,
		arg.ID,
		arg.IntegrationID,
		arg.ItemType,
		arg.ExternalID,
		arg.ExternalAccountCode,
		arg.ExternalName,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
